function isHelpToken(token) {
  return token === '-h' || (token.startsWith('-h') && !token.startsWith('--'));
}

function splitLongToken(token) {
  const equalsIndex = token.indexOf('=');
  if (equalsIndex === -1) {
    return { optionToken: token, attachedValue: null };
  }

  return {
    optionToken: token.slice(0, equalsIndex),
    attachedValue: token.slice(equalsIndex + 1),
  };
}

function matchLongOptions(optionToken) {
  return LONG_OPTION_DEFS.filter((definition) => definition.canonical.startsWith(optionToken));
}

function shouldRejectAsMissingValue(token) {
  if (token === undefined) {
    return true;
  }

  if (token === '-') {
    return false;
  }

  if (token.startsWith('--')) {
    return true;
  }

  if (!token.startsWith('-')) {
    return false;
  }

  if (isHelpToken(token)) {
    return true;
  }

  return !isNegativeNumberToken(token);
}

